    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val FCI_Command_Intake_i_fcs_coordination_process_fci_command_intake_id = Arch.FAA_FCS_Coordination_Root_Instance_fcs_coordination_process_fci_command_intake.id
