    val AP_Availability_Intake_i_fcs_coordination_process_ap_availability_intake_id = Arch.FAA_FCS_Coordination_Root_Instance_fcs_coordination_process_ap_availability_intake.id
    val Flight_Guidance_Coordination_i_fcs_coordination_process_flight_guidance_coordination_id = Arch.FAA_FCS_Coordination_Root_Instance_fcs_coordination_process_flight_guidance_coordination.id
    val Autopilot_Coordination_i_fcs_coordination_process_autopilot_coordination_id = Arch.FAA_FCS_Coordination_Root_Instance_fcs_coordination_process_autopilot_coordination.id
    val FCS_Snapshot_Publication_i_fcs_coordination_process_fcs_snapshot_publication_id = Arch.FAA_FCS_Coordination_Root_Instance_fcs_coordination_process_fcs_snapshot_publication.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case FCI_Command_Intake_i_fcs_coordination_process_fci_command_intake_id =>
          val prefix = "FCI_Command_Intake_i_fcs_coordination_process_fci_command_intake_RM_TestSuite"
          val path = testRoot /+ ISZ("faa_fcs_coordination","FAA_FCS_Coordination")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package faa_fcs_coordination.FAA_FCS_Coordination
                |
                |import org.sireum._
                |import faa_fcs_coordination.FAA_FCS_Coordination._
                |
                |class ${suiteName} extends FCI_Command_Intake_i_fcs_coordination_process_fci_command_intake_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Attitude_Condition_Intake_i_fcs_coordination_process_attitude_condition_intake_id =>
          val prefix = "Attitude_Condition_Intake_i_fcs_coordination_process_attitude_condition_intake_RM_TestSuite"
